column3:
a: {dependsOn: relate() & acyclic() & [path($.b), path($.c)]}
b: {dependsOn: relate() & acyclic() & [path($.d)]}
c: {dependsOn: relate() & acyclic() & [path($.d)]}
d: {}

a: {dependsOn: relate() & acyclic() & inverse(usedBy) & [path($.b)]}
b: {dependsOn: relate() & acyclic() & inverse(usedBy) & [path($.a)]}
a: {dependsOn: relate()}
b: {usedBy: relate() & [path($.a)]}
a: {usedBy: relate() & [path($.b)]}

%A = re("^[$]")
%B = re("[ab]$")
a: {dependsOn: relate() & [&: %A & %B] & acyclic() & [path($.b)]}
b: {dependsOn: relate() & acyclic() & [path($.a)]}
